import React, { useEffect, useState, useRef } from "react";

import { getStore, updStore, gen16CodeId, ObjectKeys, parseQuery, parseDateMMDDYYYY, AccountYears, fetchEncryptStream, qryStore } from "../../../stores/Utils";

import {SearchInput_Cmpt, SvgIcon_Cmpt, CalendarPicker_Cmpt, LoadingColorSpinner_Cmpt, CheckBoxSlide_Cmpt } from "../../../components";

import "./styles.css"
import {  search_operations,  filter_operations, getall_operations, get_all_opera, filter_date_operations } from "../services/server_fetching";
import {  ComprobanteItem_Cmpt, ViewComprobanteCierre_Cmpt } from "..";
import { getall_subaccount, getall_account, get_balances_by_type } from "../../CuentasContables/services/server_fetching";
import { useNavigate, useLocation } from "react-router";
import WithScroll from "../../../components/scroll-decorator";
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import { OpenToast } from "../../../components/Toast";
import DeleteAlert from "../../Inventory/component/deleteAlert";
import DropDwnPickerSearchComponent from "../../../components/DropDwnPickerSearch";



const CalendarModalPicker = CalendarPicker_Cmpt();

const ViewComprobante = ViewComprobanteCierre_Cmpt();

const SearchInput = SearchInput_Cmpt();

const ComprobanteItem = ComprobanteItem_Cmpt();
const Svg = SvgIcon_Cmpt();

const LoadingColorSpinner = LoadingColorSpinner_Cmpt();


const CheckBoxSlide = CheckBoxSlide_Cmpt();






const coll2list = "collComprobantes2list"
//


const ComprobantesList  = ({  }) => {
	const [, set_obs] = useState(0);
	const [range, set_range] = useState(64);
	const [inReview, setInReview] = useState(false);
	const [hasError, setHasError] = useState(false);

	
	const [loadingPrint, setLoadingPrint] = useState(false);


	const initialize = useRef(false);
	const loadingData = useRef(false);
	const loadingCompRef = useRef(null);
	const listDataRef = useRef(null);


	

	let location = useLocation();
	const navigate = useNavigate();


	const searchHash = location.search?.split("?")?.[1];
	const router = parseQuery(searchHash);

	useEffect(() => {
		setTimeout(() => {
			
			if(router?.cId){
				updStore("search_acc_record",router?.cId);
				search_operations(loadList)
			}
			get_balances_by_type("comp_under_review","comp_under_review",cb_result);
			
		}, 350);
	},[router?.cId]);



	useEffect(() => {
		if (!initialize.current) {
			initialize.current = true;
			set_obs(gen16CodeId());
			getall_account(cb_result)
			getall_subaccount(handle_getall);
			get_balances_by_type("global_accounts","global_account_params",cb_result);

			
		}
	});



	const filterAcc  = (v)  => {
		
		let flAcc = []
		getStore("account_list").map((e)=>{
			
			
			if(v){
				let ss = v.toLowerCase();
			
				let isV1 = e?.code ? e?.code?.toString().toLowerCase()?.indexOf(ss)>=0 : false;
				let isV2 = e?.name? e?.name?.toString().toLowerCase()?.indexOf(ss)>=0: false;
				
				if(isV1 || isV2){
					flAcc.push({id: e?.accountId, label: `${e?.code}-${e?.name}`});
				}
			}
		});
		return flAcc
	}

	
	const filterSubAcc  = (v)  => {
				
		let flAcc = []
		getStore("sub_account_list").map((e)=>{
			if(v){
				let ss = v.toLowerCase();
				let isV1 = e?.subAccount ? e?.subAccount?.toString().toLowerCase()?.indexOf(ss)>=0 : false;
				let isV2 = e?.subAccountName? e?.subAccountName?.toString().toLowerCase()?.indexOf(ss)>=0: false;
				
				if(isV1 || isV2){
					flAcc.push({id: e?.sub_accountId, label: `${e?.subAccount}-${e?.subAccountName}`});
				}
			}
		});
		return flAcc
	}



	const drawBox=(e)=>{
		loadingCompRef?.current?.setAttribute("show",e);
		listDataRef?.current?.setAttribute("loading",e);
	}



	const openUpdateView =  () => {
		//
	}


	const openAddView =  (v) => {
		navigate({
			pathname: "/entries"
		});
	}

	const handleChange =  (v) => {
		updLoading(true);
	}


	const handle_search =  (v) => {
		//set_loading(true);
		search_operations(loadList);
	}

	


	const loadList =  () => {
		let docdata = {...getStore("comprobante_by_doc")};
		updStore(coll2list,docdata);
		if(getStore("has_filter_review") && inReview){
			updStore(coll2list,filterIsUnderReview(docdata));
		}
		else if(getStore("has_filter_comp_error") && hasError){
			updStore(coll2list,filterHasError(docdata));
		}

		
		cb_result();
	};



	const handle_getall=  () => {
		updStore("comprobante_list", null);
		updStore("comprobante_by_doc", null);
		loadList();
	}

	
	const updLoading = (v) => {
		if(v){
			if(!loadingData.current){
				loadingData.current = v;
				drawBox(v);
			}
		}else{
			if(loadingData.current){
				loadingData.current = v;
				drawBox(v);
			}
		}
	}


	const cb_result = async (f, v) => {
		updLoading(false);
		if(range!==64){
			set_range(64);
		}else{
			set_obs(gen16CodeId())
		}
		
	};


	const loadMore=  () => {
		set_range(v=>v+64)
	}


	const handleFilterInReview=  () => {
		let docdata = {...getStore("comprobante_by_doc")};
		updStore(coll2list,docdata);
		if(getStore("has_filter_review") && !inReview){
			updStore(coll2list,filterIsUnderReview(docdata));
		}
		setInReview(!inReview);
	}


	const handleFilterhasError=  () => {
		let docdata = {...getStore("comprobante_by_doc")};
		updStore(coll2list,docdata);
		if(getStore("has_filter_comp_error") && !hasError){
			updStore(coll2list,filterHasError(docdata));
		}
		setHasError(!hasError);
	}



	const confirmCalendar = (v) => {
		updLoading(true);
		if(v?.initDate && v?.lastDate ){
			let nv = {...v};
			nv.initDate = nv.initDate -100;
			nv.lastDate = nv.lastDate + 86380000;
			updStore("date_range_comps",nv);
		}
		filter_operations(loadList);
	}
	


    const openCalendar = () => {
        let modal_data = {};
        modal_data["zIndex"] = 950;
        modal_data["height"] = "80vh";
        // data['observeResize']=true;
        modal_data["props"] = { minHeight: "1vh", overlay: true };
        modal_data["content"] = 
			<CalendarModalPicker 
				onConfirm={confirmCalendar} 
				init={getStore("date_range_comps")?.initDate}
				last={getStore("date_range_comps")?.lastDate}
				isRange={true}
				colors={ {
					"--calendar-primary-color":"var(--hrm_palette-blue-purple)",
					"--calendar-primary-backcolor":"var(--primary-light)",
					"--calendar-light-backcolor":"var(--hrm_palette-general-background-b)",
					"--calendar-primary-hover-backcolor":"var(--hrm_palette-blue-purple_100)",

					"--calendar-light-300":"var(--disabled)",
					"--calendar-light-200":"var(--dark-800)",
					"--calendar-light-100":"var(--dark-900)",
					"--calendar-dark-800":"var(--hrm_palette-blue-purple_100)",
					"--calendar-white-100":"var(--light-100)",
					"--calendar-white":"var(--dark-700)",
					
					"--calendar-selected_lbl_color":"var(--light-400)",
					
					"--calendar-selected_lbl_color":"var(--primary-blue--color-30)",
				  }}
			/>
        
        OpenModal(modal_data);
	}
	

	let dateRangeString = getStore("date_range_comps")?.initDate && parseDateMMDDYYYY(getStore("date_range_comps")?.initDate)  + " - " +parseDateMMDDYYYY(getStore("date_range_comps")?.lastDate);


	const validateRes = () => {
		updLoading(true);
		OpenToast({ text: "Verificacion de comprobantes completada", timeout: 3500 });
		set_obs(gen16CodeId())
		if(getStore("showAllCmpbnt")){
			loadList();
		}
	}

	const checkCmp = () => {
		//getall_operations(validateRes)

		filter_date_operations()
	}

	const showAll = (nv) => {
		updStore("showAllCmpbnt",nv);
		set_obs(gen16CodeId())
	}

	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	const refresh =  () => {
		getall_operations(updObs)
	}

	const closeEv =  () => {
		navigate({
			search: ``,
		});
		
	}

	


	const calcApertura =  () => {

		setLoadingPrint(true);
		get_all_opera(openViewComprobante);
		
	}




	
	const openViewClosingYear =  (modalId) => {
		let modaldata = {};
		modaldata["id"] = modalId;
		modaldata["zIndex"] = 490;
		modaldata["height"] = "40vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
		let bdyM = <div>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"Cerrando el Año contable"}
			</h4>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"Generando el asiento de apertura"}
			</h4>
		</div>

		let titleCm = <div className="_dsplFlx ">
			<div className="centerBx"  style={{padding: 4, marginRight: 20}}>
				
				<LoadingColorSpinner stroke={"var(--hrm_palette-selected-nav-text)"} size={24} strokeW={8}/>
				
			</div>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"Terminando Cierre de Año !!!"}
			</h4>
		</div>



		modaldata["content"] = <DeleteAlert
			label={titleCm} 
			labelColor={"var(--hrm_palette-selected-nav-text)"} 
			body={bdyM} 
			btnConfirm={"OK"}
			confirm={checkCmp}
			done={((v)=>{
				v && CloseModal({id:v});
			})}
		/>
		OpenModal(modaldata);
	}

	const openViewComprobante =  (data) => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(Date.now() > lastTimeCallModal){
			updStore("lastTimeCallModal", Date.now()+320);
			const searchHash = location.search?.split("?")?.[1];
			const router = parseQuery(searchHash);
			if(!(router?.cId && router?.cId=== data.comprobanteId)){
				navigate({
					search: `?cId=${data.comprobanteId}`,
				});
			}
			updStore("show_comprobante", data);
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "80vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: closeEv  };
			modaldata["content"] = <ViewComprobante 
				confirm={refresh} 
				item={data}
				confirmYearClose={openViewClosingYear}
			/>
			setLoadingPrint(false);
			
			OpenModal(modaldata);
		}
	}








	const checkCmpAlert =  () => {
		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "40vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
		let bdyM = <div>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"Esta funcion consume recursos y puede tomar un tiempo"}
			</h4>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"Esta seguro que desea ejecutarlo ???"}
			</h4>
		</div>

		let titleCm = <div className="_dsplFlx ">
			<div className="centerBx">
				<Svg 
					name={"alert"} 
					color={"var(--hrm_palette-selected-nav-text)"}
				/>		
			</div>
			<h4 className="" style={{padding: 4, margin: 0}}>
				{"Revisar comprobantes!!!"}
			</h4>
		</div>



		modaldata["content"] = <DeleteAlert
			label={titleCm} 
			labelColor={"var(--hrm_palette-selected-nav-text)"} 
			body={bdyM} 
			btnConfirm={"OK"}
			confirm={checkCmp}
		/>
		OpenModal(modaldata);
	}
	


	const updKeys = (f,v) => {
		updStore(f,v);
		handle_search();
	}	


	// 
	return (

		<div className="">
			<div className="accounts_header">
				<h2>Comprobantes</h2>
				{AccountYears()[getStore("date_current_year")]?.isClosed?null:
				<div className="_dsplFlx ">
					<div>
						<p className="group_title addBtn purple" onClick={openAddView}>
							Agregar Comprobantes
						</p>
					</div>
					
					<div>
						<p className="group_title addBtn purple" onClick={checkCmpAlert}>
							Revisar Comprobantes
						</p>
					</div>
					<div className="">
					{loadingPrint?
						<div className="icon_compr _dsplFlx" style={{marginTop:10, marginRight: 15}}>
							<div className="lbl_saving ">
								Calculando Asiento ... 
							</div>
							<LoadingColorSpinner stroke={"var(--hrm_palette-blue-purple)"} size={24} strokeW={8}/>
						</div>
						:
							<div>
								<p className="group_title addBtn purple" onClick={calcApertura}>
								Calcular Asiento de Apertura
								</p>
							</div>
						}
					</div>


					
					<div className="_dsplFlx " style={{marginTop: 20}}>
						<CheckBoxSlide
							initvalue={getStore("showAllCmpbnt")}
							keyCode={57}
							updChange={(e)=>showAll(e)}
						/>
						<span className={`checklabel`}>
							{"Mostar Todos"}
						</span>
					</div>

					
				</div>
				}
				<div className="_dsplFlx " style={{marginTop:14}}>
					<SearchInput
						placeholder={"Buscar ...."} 
						width={360}
						obs={set_obs}
						fetchData={handle_search}
						change={handleChange}
						callempty={handle_getall}
						keyFlds={"search_acc_record"}
					/>
					<div className="flexSpace"/>
					<div className="_dsplFlx ">
						<div className="total_comprobante_title">
							No de Comprobantes: 
						</div>
						<div className="total_comprobante gray">
							<span>
								{ObjectKeys(getStore(coll2list))?.length}
							</span>
						</div>
					</div>
				</div>
			</div>
			<div className="_dsplFlx " style={{marginBottom:14, maxWidth:500}}>
			
				<div className={"filter_date_btn _dsplFlx"} onClick={openCalendar} style={{minWidth: 200}}>
					<div className="lbl date">
							{dateRangeString || "Fecha"}
					</div>
					<Svg name={"calendar"} color={"#66666"}/>
				</div>
				{getStore("has_filter_review")?
				<div 
					className={"filter_cmp_btn _dsplFlx"} 
					style={{
						"--filter_cmp_btn_color": inReview?"var(--hrm_palette-color-orange-800)":"var(--hrm_palette-success-fg)",
						"--filter_cmp_btn_bck-color":inReview?"var(--hrm_palette-color-orange-100)":"var(--hrm_palette-success-100)",
					}} 
					onClick={handleFilterInReview}
				>
					<div className="lbl">
						{inReview?"En Revision":"Todos"}
					</div>
					<Svg name={inReview?"alert":"success"} color={"#66666"}/>
				</div>
				:null}
				{getStore("has_filter_comp_error")?
				<div 
					className={"filter_cmp_btn _dsplFlx"} 
					style={{
						"--filter_cmp_btn_color": hasError?"var( --hrm_palette-selected-nav-text)":"var(--hrm_palette-success-fg)",
						"--filter_cmp_btn_bck-color":hasError?"var( --hrm_palette-selected-nav-text-100)":"var(--hrm_palette-success-100)",
						marginLeft:12
					}} 
					onClick={handleFilterhasError}
				>
					<div className="lbl">
						{hasError?"Contiene errors":"OK"}
					</div>
					<Svg name={hasError?"alert":"success"} color={"#66666"}/>
				</div>
				:null}
				<div className="flexSpace"/>
				<div className="_dsplFlx spaceAround"  style={{padding: 3,minWidth: "fit-content"}}>
					<DropDwnPickerSearchComponent 
						init={getStore("account_operafilter")}
						lbl_empty={"Cuenta"} 
						func={filterAcc} 
						onSelect={(e)=>updKeys("account_operafilter",e?.id)}
						background={"#f9f9f9"}
						color={"var(--hrm_palette-blue-purple)"}
						direction={"left"}
						width={"320px"}
					/>
				</div>
				<div className="_dsplFlx spaceAround"  style={{padding: 3,minWidth:  "fit-content"}}>
					<DropDwnPickerSearchComponent 
						init={getStore("sub_account_operafilter")}
						lbl_empty={"Sub Cuenta"} 
						func={filterSubAcc} 
						onSelect={(e)=>updKeys("sub_account_operafilter",e?.id)}
						background={"#f9f9f9"}
						color={"var(--hrm_palette-blue-purple)"}
						direction={"left"}
						width={"320px"}
					/>
				</div>
			</div>


			<div className="accounts_container " >
				<div style={{height: 55}}>
					<MenuAcc />
				</div>
				<div  className="loading_animation_container" style={{marginTop:2}} ref={loadingCompRef}>
					<div className="load_animation"/>
					<div className="_dsplFlx"  style={{marginTop:32}}>
						<div className="flexSpace"/>
						<div className="icon_compr align_itm " >
							<div className="lbl_saving">
									Loading ... 
							</div>
							<LoadingColorSpinner stroke={"#646cff"} size={24} strokeW={8}/>
						</div>
						<div className="flexSpace"/>
					</div>
				</div>
				
				<div  id={"scollVhComprobantesList"}  className="clients_container"  ref={listDataRef}>
					{getStore(coll2list) && ObjectKeys(getStore(coll2list))?.map((cid, index)=>{
						return (
							<ComprobanteItem 
								data={getStore(coll2list)[cid]} 
								elmId={cid} 
								key={cid}
								openUpdateView={openUpdateView}
								handleRefreshAll={handle_getall}
								inReview={inReview}
								hasError={hasError}
								updRvw={set_obs}
								range2Scroll={range-index===32}
								show={index < range}
								inx={index}
								updRange={loadMore}
							/>
						)
					})}
				</div>
			</div>
			
		</div>
	);
};

export default ComprobantesList;







const MenuAcc = ({}) =>{
	const [float, setFloat] = useState(false);




	const handleScroll = (e) => {
		if(e>295){
			!float && setFloat(true);
		}else{
			float && setFloat(false)
		}
	}


	return (
		<div className={`header_tbl ${float?"_floating":""}`} >
			<div className="_dsplFlx hdr_bar purple">
				<div className="_dsplFlx tr_bar_90">
				
					<div className=" tr_bar_20" >
						Fecha
					</div>
					<div className=" tr_bar_25">
						Comprobante
					</div>
					<div className=" tr_bar_55">
						Descripcion
					</div>
				</div>
				<div className="flexSpace"/>
				<div className="icon tr_bar_5" >
				</div>
			</div>
			<WithScroll scrollhandler={handleScroll} />
		</div>
	)
}




function filterIsUnderReview(arr1) {
    var newArr = [];
	ObjectKeys(arr1).map((s) => {
		let itm = arr1[s];
		if (getStore("comp_under_review")?.inReview?.[itm?.comprobanteId]) {
			newArr.push(itm);
		}
	})
	return newArr;
}

function filterHasError(arr1) {
    var newArr = [];
	ObjectKeys(arr1).map((s) => {
		let itm = arr1[s];
		if (getStore("comp_under_review")?.hasError?.[itm?.comprobanteId] || getStore("comprobante_w_erros")?.[itm?.comprobanteId]) {
			newArr.push(itm);
		}
	})
	return newArr;
}





//  y2svXsYrLseUUtI4  Patrimonio